	zone = "Moonglade",
	unlock = {
		{ type = "zone" },
		{ type = "map" },
	},
	regionKind = "zone",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Moonglade is a hidden vale in the mountains of northern {link:kalimdor}Kalimdor{/link}, between {link:felwood}Felwood{/link} and {link:winterspring}Winterspring{/link}. A still lake lies at its heart, ringed by silver grass and ancient trees, and on its shores stands the village of {link:nighthaven}Nighthaven{/link}. This is the sacred ground of the {link:cenarion-circle}Cenarion Circle{/link}, the order of druids, and the seat of {link:keeper-remulos}Keeper Remulos{/link}, son of {link:cenarius}Cenarius{/link}. No army holds it. Night elf and {link:tauren}tauren{/link} walk its paths as friends, and its wardens suffer no violence within its borders.]=],
		},
		{
			title = "Origins",
			text = [=[No chronicle records the year when the druids first made Moonglade their refuge. Its names tell something of its past. The lake bears the name of Elune, the moon goddess of the {link:night-elves}night elves{/link}. The barrows in the east bear the name of {link:malfurion-stormrage}Malfurion Stormrage{/link}, the first druid, whose followers learned to sleep for long ages in the {link:emerald-dream}Emerald Dream{/link}. The druids say that those who hibernate in Moonglade sleep under the keeper's watch. It has never been a city or a fortress, only a place of teaching and of rest.]=],
		},
		{
			title = "The Present Day",
			text = [=[The glade is at peace, but the Circle that dwells in it is not. {link:malfurion-stormrage}Malfurion{/link} sleeps and has not returned. In {link:darnassus}Darnassus{/link}, Arch Druid {link:fandral-staghelm}Fandral Staghelm{/link} leads the druids of the night elves, and he and {link:keeper-remulos}Keeper Remulos{/link} have come to mistrust each other. Each suspects the other of trickery, while the strange corruption of {link:teldrassil}Teldrassil{/link} goes on unhealed. Moonglade has turned outward instead. Its druids have welcomed the {link:tauren}tauren{/link}, and through them the {link:horde}Horde{/link}. Its envoys seek help from any people willing to give it: against poison in {link:darkshore}Darkshore{/link}, against the Felvine of Eldre'Thalas, and against an ancient evil stirring in {link:silithus}Silithus{/link}. Lately druids of the {link:skyborne}shen'dorei{/link}, from a far island in the sky, have come to {link:nighthaven}Nighthaven{/link}, and a spirit of their homeland has come to meet them.]=],
		},
		{
			title = "Inhabitants",
			text = [=[• {b}The druids of the {link:cenarion-circle}Cenarion Circle{/link}.{/b} Night elves and {link:tauren}tauren{/link} who teach, study and sleep in the glade, led by {link:keeper-remulos}Keeper Remulos{/link} and his majordomo, {link:rabine-saturna}Rabine Saturna{/link}.
• {b}The wardens of Moonglade.{/b} {link:sentinels}Sentinels{/link} of the Circle who keep the peace of the glade and guard its shrine.
• {b}The great spirits.{/b} Ancient spirits of the wild, who teach young druids the shapes of their kind.
• {b}The restless dead.{/b} Within the {link:stormrage-barrow-dens}Stormrage Barrow Dens{/link}, the spirits of fallen Druids of the Claw wander in anger.
• {b}The {link:timbermaw-furbolgs}Timbermaw{/link}.{/b} The furbolgs of {link:timbermaw-hold}Timbermaw Hold{/link} guard the tunnels that are the only road into the glade, and they do not welcome every traveller.]=],
		},
		{
			title = "History",
			text = [=[• {b}The Age of the Ancients.{/b} The druids learned their craft from {link:cenarius}Cenarius{/link} in the {link:war-of-the-ancients}War of the Ancients{/link}, and kept it through ten thousand years, most of them spent in sleep.
• {b}The {link:third-war}Third War{/link}.{/b} When the {link:burning-legion}Burning Legion{/link} returned, the druids woke to fight. Cenarius fell in {link:ashenvale}Ashenvale{/link}, and at the {link:battle-of-mount-hyjal}Battle of Mount Hyjal{/link} {link:nordrassil}Nordrassil{/link} gave its power to destroy {link:archimonde}Archimonde{/link}.
• {b}The Open Circle.{/b} After the war, the Circle took in {link:tauren}tauren{/link} druids, first among them {link:hamuul-runetotem}Hamuul Runetotem{/link}. Moonglade became the common ground of both peoples.]=],
		},
		{
			title = "Lore of the Glade",
			text = [=[• The druids tell of Omen, a great wolf of the {link:war-of-the-ancients}War of the Ancients{/link} whom demonic magic turned against his allies. Brought down in Moonglade, he sleeps in {link:lake-elune-ara}Lake Elune'ara{/link} and stirs once a year, at the Lunar Festival.
• South of the glade, beyond {link:felwood}Felwood{/link} and {link:winterspring}Winterspring{/link}, rise the heights of {link:mount-hyjal}Mount Hyjal{/link}, where {link:nordrassil}Nordrassil{/link} still stands. The barrows of the Druids of the Claw run deep beneath that mountain too, and the deepest of them are called {link:the-barrow-deeps}The Barrow Deeps{/link}.
• {link:umber}Umber{/link}, the archivist of {link:nighthaven}Nighthaven{/link}, warns every visitor never to keep {link:rabine-saturna}Rabine Saturna{/link} waiting. Those who do, he says, may find themselves doused in honey.]=],
		},
	},
})

