	sections = {
		{
			title = "Summary",
			text = [=[Keeper Remulos is a son of the demigod {link:cenarius}Cenarius{/link} and the guardian of {link:moonglade}Moonglade{/link}. Like his father, he is a being of the wild, as much forest as flesh. He keeps watch over the sacred glade and over the druids who sleep within it, and he guides the {link:cenarion-circle}Cenarion Circle{/link} in its work: the preservation of nature and of balance.]=],
		},
		{
			title = "Significance",
			text = [=[With {link:malfurion-stormrage}Malfurion Stormrage{/link} lost in the {link:emerald-dream}Emerald Dream{/link}, the druids have two centers, and two leaders. In {link:darnassus}Darnassus{/link}, Arch Druid {link:fandral-staghelm}Fandral Staghelm{/link} rules from the boughs of the new World Tree. In {link:moonglade}Moonglade{/link}, Remulos keeps the older ground. The two no longer trust each other. Remulos has chosen to open the glade to all who serve the living world, {link:tauren}tauren{/link} and {link:night-elves}night elf{/link}, {link:horde}Horde{/link} and {link:alliance}Alliance{/link} alike. It is from his glade, not from the Arch Druid's city, that the Circle now calls mortal champions against the dangers of {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "A Son of Cenarius",
			text = [=[The keepers of the grove are the sons of {link:cenarius}Cenarius{/link}, and Remulos is one of them. His brother Zaetar was the first son. Long ago Zaetar sought out Princess Theradras, a great power of elemental earth, and she bore him the first centaurs. His own children turned on him and killed him, and Theradras took his remains into the caves of {red:maraudon}Maraudon{/red}. Remulos believed his brother lost for ever to arrogance and rage. Then, in the {link:third-war}Third War{/link}, his father fell to the orcs in {link:ashenvale}Ashenvale{/link}. Remulos has lost much to the mortal races. He has not closed {link:moonglade}the glade{/link} to them.]=],
		},
		{
			title = "Deeds",
			text = [=[• He guards {link:moonglade}Moonglade{/link} and the druids who hibernate there.
• He guides the {link:cenarion-circle}Cenarion Circle{/link} from the {link:shrine-of-remulos}Shrine of Remulos{/link}.
• Through his majordomo, {link:rabine-saturna}Rabine Saturna{/link}, he calls on the peoples of the world to aid the Circle in {link:silithus}Silithus{/link} and in the ruins of Eldre'Thalas.
• He welcomes the {link:tauren}tauren{/link}, and the {link:horde}Horde{/link} through them, into the glade.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written of Remulos before the present age: what part he played in the wars of the ancient world, or when he first came to keep {link:moonglade}Moonglade{/link}. This entry records only what his words and his post reveal.]=],
		},
