			text = [=[Loganaar is often the one who hears when someone far away asks for a druid's help. When a hunter named {link:torwa-pathfinder}Torwa Pathfinder{/link} sent word from {link:un-goro-crater}Un'Goro Crater{/link} that only a druid could aid him, it was Loganaar who passed the message on.]=],
